+function PemToCert(const MultiPartPem: RawUtf8): RawByteString;
+var
+  P: PUtf8Char;
+  pem: RawUtf8;
+  k: TPemKind;
+begin
+  FastAssignNew(result);
+  P := pointer(MultiPartPem);
+  repeat
+    pem := NextPem(P, @k);
